import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { PasswordInput } from "@/registry/erbium/ui/password-input";

const PasswordInputNewPassword = () => (
  <Field className="max-w-sm">
    <FieldLabel>New password</FieldLabel>
    <PasswordInput autoComplete="new-password" minLength={8} />
    <FieldDescription>Use at least 8 characters.</FieldDescription>
  </Field>
);

export default PasswordInputNewPassword;

import PasswordInputNewPassword from "../examples/password-input-new-password";

const Example = () => <PasswordInputNewPassword />;

export default Example;
